sharedfs_boot_state=$(systemctl show cloud-early-config.service -p ActiveState -p SubState -p Result); if ! printf '%s\n' "$sharedfs_boot_state" | grep -qx 'ActiveState=active' || ! printf '%s\n' "$sharedfs_boot_state" | grep -qx 'SubState=exited' || ! printf '%s\n' "$sharedfs_boot_state" | grep -qx 'Result=success'; then echo 'SHAREDFS_BOOTSTRAP_PENDING: waiting for guest network initialization' >&2; exit 75; fi; 